body { margin: 0; background: #f5f7fb; color: #172033; font: 16px/1.5 system-ui, sans-serif; }
.container { width: min(720px, calc(100% - 32px)); margin: 56px auto; padding: 32px; background: #fff; border: 1px solid #e1e6ef; border-radius: 12px; box-shadow: 0 8px 24px #1720330d; }
h1 { margin: 0 0 24px; font-size: 2rem; }
.create-form { display: grid; grid-template-columns: 1fr auto; gap: 8px 12px; align-items: center; }
.create-form label { grid-column: 1 / -1; font-weight: 600; }
input { min-width: 0; padding: 10px 12px; border: 1px solid #aab4c4; border-radius: 6px; font: inherit; }
button { padding: 10px 16px; border: 0; border-radius: 6px; background: #2458c6; color: white; font: inherit; font-weight: 600; cursor: pointer; }
button:hover { background: #1947a8; }
button:focus-visible, input:focus-visible { outline: 3px solid #8ab4ff; outline-offset: 2px; }
.alert { grid-column: 1 / -1; margin: 0; color: #b42318; }
.project-list { display: grid; gap: 10px; margin-top: 24px; }
.project-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 14px 16px; border: 1px solid #e1e6ef; border-radius: 8px; }
.project-row span { overflow-wrap: anywhere; }
@media (max-width: 480px) { .container { margin: 20px auto; padding: 22px; } .create-form { grid-template-columns: 1fr; } .create-form label, .alert { grid-column: 1; } }

